// controllers/review-controller-mcq.ts
var import_obsidian7 = require("obsidian");

// ui/mcq-modal.ts
var import_obsidian6 = require("obsidian");

// utils/rating.ts
function mapScoreToSm2Response(score) {
  if (score >= 0.95)
    return 5 /* PerfectRecall */;
  if (score >= 0.8)
    return 4 /* CorrectWithHesitation */;
  if (score >= 0.6)
    return 3 /* CorrectWithDifficulty */;
  if (score >= 0.4)
    return 2 /* IncorrectButFamiliar */;
  if (score > 0)
    return 1 /* IncorrectResponse */;
  return 0 /* CompleteBlackout */;
}
function mapScoreToFsrsRating(score) {
  if (score >= 0.9)
    return 4 /* Easy */;
  if (score >= 0.7)
    return 3 /* Good */;
  if (score >= 0.5)
    return 2 /* Hard */;
  return 1 /* Again */;
}

// models/mcq-scoring.ts
function scoreAnswer(answer, settings) {
  let questionScore = 0;
  if (settings.mcqDeductFullMarkOnFirstFailure) {
    if (answer.attempts === 1 && answer.correct) {
      questionScore = 1;
    } else {
      questionScore = 0;
    }
  } else {
    if (answer.correct && answer.selectedAnswerIndex !== -1) {
      if (answer.attempts === 1) {
        questionScore = 1;
      } else if (answer.attempts === 2) {
        questionScore = 0.5;
      }
    }
  }
  if (questionScore > 0 && answer.timeToAnswer > settings.mcqTimeDeductionSeconds) {
    questionScore -= settings.mcqTimeDeductionAmount;
    questionScore = Math.max(0, questionScore);
  }
  return questionScore;
}
function scoreSession(answers, questionCount, settings) {
  let totalScore = 0;
  answers.forEach((answer) => {
    totalScore += scoreAnswer(answer, settings);
  });
  return questionCount > 0 ? totalScore / questionCount : 0;
}
var SM2_LABELS = {
  [0 /* CompleteBlackout */]: "Complete blackout",
  [1 /* IncorrectResponse */]: "Incorrect",
  [2 /* IncorrectButFamiliar */]: "Incorrect but familiar",
  [3 /* CorrectWithDifficulty */]: "Correct with difficulty",
  [4 /* CorrectWithHesitation */]: "Correct with hesitation",
  [5 /* PerfectRecall */]: "Perfect recall"
};
function suggestedRating(score, algorithm) {
  var _a2;
  if (algorithm === "fsrs") {
    const rating2 = mapScoreToFsrsRating(score);
    return { rating: rating2, label: FsrsRating[rating2] };
  }
  const rating = mapScoreToSm2Response(score);
  return { rating, label: (_a2 = SM2_LABELS[rating]) != null ? _a2 : String(rating) };
}

